/* v18 free client */
window.addEventListener("error", function(){
  try {
    const g=document.getElementById("cookieGate");
    if(g && g.classList.contains("hidden")){ g.style.display="none"; g.style.pointerEvents="none"; }
    document.documentElement.classList.remove("cookie-gate-open");
    document.body.classList.remove("cookie-gate-open");
    document.documentElement.style.removeProperty("overflow");
    document.body.style.removeProperty("overflow");
  } catch(_) {}
});

/* ===== Initial page position =====
   Do not restore an old mobile scroll position when opening the site.
   Anchor links (e.g. #pricing) are left untouched. */
(function () {
  try { history.scrollRestoration = "manual"; } catch (_) {}
  if (!location.hash) {
    window.scrollTo(0, 0);
    window.addEventListener("pageshow", function () {
      if (!location.hash) window.scrollTo(0, 0);
    }, { once: true });
  }
})();


/* ===== Cookie consent gate =====
   Consent is requested once per browser/device. */
const COOKIE_CONSENT_NAME = "space_cookie_consent";
const COOKIE_CONSENT_VERSION = "1";
let cookieConsentGranted = false;

function hasCookieConsent() {
  try {
    return localStorage.getItem(COOKIE_CONSENT_NAME) === COOKIE_CONSENT_VERSION ||
      document.cookie.split(";").some(c => c.trim().startsWith(COOKIE_CONSENT_NAME + "=accepted"));
  } catch (_) {
    return false;
  }
}

function setConsentCookie() {
  const maxAge = 60 * 60 * 24 * 3650; // 10 years
  try { localStorage.setItem(COOKIE_CONSENT_NAME, COOKIE_CONSENT_VERSION); } catch (_) {}
  document.cookie = `${COOKIE_CONSENT_NAME}=accepted; Max-Age=${maxAge}; Path=/; SameSite=Lax`;
}

function closeCookieGate() {
  const gate = document.getElementById("cookieGate");
  if (!gate) return;
  cookieConsentGranted = true;
  gate.classList.add("hidden");
  gate.setAttribute("aria-hidden", "true");
  document.body.classList.remove("cookie-gate-open");
}

function openCookieGate() {
  const gate = document.getElementById("cookieGate");
  if (!gate) return;
  if (hasCookieConsent()) {
    closeCookieGate();
    return;
  }
  cookieConsentGranted = false;
  gate.classList.remove("hidden");
  gate.classList.remove("rejected-state");
  gate.setAttribute("aria-hidden", "false");
  document.body.classList.add("cookie-gate-open");
}

function acceptCookies(event) {
  if (window.spaceAcceptCookies) return window.spaceAcceptCookies(event);
  if (event) { event.preventDefault(); event.stopPropagation(); }
  setConsentCookie();
  closeCookieGate();
}

function rejectCookies(event) {
  if (event) {
    event.preventDefault();
    event.stopPropagation();
  }
  const gate = document.getElementById("cookieGate");
  const consent = document.getElementById("cookieConsentView");
  const rejected = document.getElementById("cookieRejectedView");
  if (!gate) return;
  gate.classList.add("rejected-state");
  if (consent) consent.classList.add("hidden");
  if (rejected) rejected.classList.remove("hidden");
  document.body.classList.add("cookie-gate-open");
}

function setupCookieGate() {
  const accept = document.getElementById("cookieAccept");
  const reject = document.getElementById("cookieReject");
  if (accept && !accept.dataset.cookieBound) {
    accept.dataset.cookieBound = "1";
    accept.type = "button";
    accept.addEventListener("click", acceptCookies, {passive:false});
  }
  if (reject && !reject.dataset.cookieBound) {
    reject.dataset.cookieBound = "1";
    reject.type = "button";
    reject.addEventListener("click", rejectCookies, {passive:false});
  }
  if (hasCookieConsent()) closeCookieGate();
  else openCookieGate();
}

