const i18nOriginalText = new WeakMap();
const i18nOriginalAttrs = new WeakMap();
function currentLang(){ return localStorage.getItem("space_lang_v2") || "ru"; }
function normalizeI18nText(value){
  return String(value ?? "").replace(/\s+/g, " ").trim();
}
const I18N_NORMALIZED = {ru:{}, en:{}, zh:{}};
function rebuildI18nNormalized(){
  for(const lang of Object.keys(I18N_NORMALIZED)){
    I18N_NORMALIZED[lang] = {};
    for(const key of Object.keys(I18N[lang] || {})){
      const value = normalizeI18nText(I18N[lang][key]);
      if(value) I18N_NORMALIZED[lang][value] = key;
    }
  }
}

