rebuildI18nNormalized();
function sourceKey(value){
  const v=normalizeI18nText(value);
  if(!v) return v;
  if(I18N.ru[v]) return v;
  const ruKey = I18N_NORMALIZED.ru[v];
  if(ruKey) return ruKey;
  const enKey = I18N_NORMALIZED.en[v];
  if(enKey) return enKey;
  const zhKey = I18N_NORMALIZED.zh[v];
  if(zhKey) return zhKey;
  return v;
}
function tr(value){
  if(value==null) return value;
  const raw=String(value);

  // Translate generic HTTP errors while preserving the status code.
  const serverError = raw.match(/^Ошибка сервера\s*\((\d{3})\)$/i);
  if(serverError){
    const code=serverError[1];
    if(currentLang()==="en") return `Server error (${code})`;
    if(currentLang()==="zh") return `服务器错误（${code}）`;
    return `Ошибка сервера (${code})`;
  }

  // Server returns the insufficient-balance error with a dynamic amount,
  // so an exact dictionary lookup cannot translate the whole sentence.
  const insufficient = raw.match(/^Недостаточно денег\.\s*На балансе\s*([\d\s.,]+)\s*₽\.?$/i);
  if(insufficient){
    const balance = insufficient[1].trim();
    if(currentLang()==="en") return `Insufficient balance. Current balance: ${balance} ₽.`;
    if(currentLang()==="zh") return `余额不足。当前余额：${balance} ₽。`;
    return `Недостаточно денег. На балансе ${balance} ₽.`;
  }

  const key=sourceKey(raw);
  let out=I18N[currentLang()][key] ?? raw;
  if(out.includes("{price}")){ const m=raw.match(/([\d\s.,]+)\s*₽/); if(m) out=out.replace("{price}",m[1].trim()); }
  return out;
}
function translateNode(node){
  if(node.nodeType!==Node.TEXT_NODE) return;
  if(node.parentElement?.closest("#languageMenu, #currentLanguage")) return;
  const raw=node.nodeValue;
  if(!raw || !raw.trim()) return;
  if(!i18nOriginalText.has(node)) i18nOriginalText.set(node,raw);
  const original=i18nOriginalText.get(node);
  const lead=(original.match(/^\s*/)||[""])[0], tail=(original.match(/\s*$/)||[""])[0];
  const value=normalizeI18nText(original);
  const key=sourceKey(value);
  const translated=I18N[currentLang()][key];
  if(translated!=null) node.nodeValue=lead+translated+tail;
}
function translateAttributes(el){
  if(el.closest?.("#languageMenu, #currentLanguage")) return;
  if(!i18nOriginalAttrs.has(el)){
    i18nOriginalAttrs.set(el,{
      placeholder:el.getAttribute("placeholder"),
      ariaLabel:el.getAttribute("aria-label"),
      title:el.getAttribute("title")
    });
  }
  const original=i18nOriginalAttrs.get(el);
  for(const [attr,key] of [["placeholder","placeholder"],["aria-label","ariaLabel"],["title","title"]]){
    if(original[key]==null) continue;
    const text=original[key], translated=I18N[currentLang()][sourceKey(text)];
    if(translated!=null) el.setAttribute(attr,translated);
  }
}
