function applyLanguage(lang,animate=true){
  if(!I18N[lang]) lang="ru";
  const old=currentLang();
  if(old===lang && document.documentElement.dataset.languageReady==="1") return;
  const body=document.body;
  if(animate && body){
    body.classList.add("language-changing");
  }
  localStorage.setItem("space_lang_v2",lang);
  document.documentElement.lang=lang==="zh"?"zh-CN":lang;
  if(body) body.dataset.i18nApplying="1";
  document.querySelectorAll("[placeholder],[aria-label],[title]").forEach(translateAttributes);
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
  let n; while(n=walker.nextNode()) translateNode(n);
  const current=document.getElementById("currentLanguage");
  if(current) current.textContent=lang==="ru"?"RU":lang==="en"?"EN":"中文";
  document.querySelectorAll("#languageMenu [data-lang]").forEach(b=>b.classList.toggle("active",b.dataset.lang===lang));
  // Refresh dynamic UI strings that are not plain HTML text nodes.
  if (typeof updateModal === "function") updateModal();
  if (typeof refreshKnownUiLanguage === "function") refreshKnownUiLanguage();
  if (typeof refreshLandingLanguage === "function") refreshLandingLanguage(lang);
  if (typeof refreshLandingStaticLanguage === "function") refreshLandingStaticLanguage(lang);
  if (typeof updateBottomDownloadGate === "function") updateBottomDownloadGate();
  if (typeof setResetStep === "function" && !document.getElementById("resetModal")?.classList.contains("hidden")) {
    const activeResetStep = !document.getElementById("resetStepRequest")?.classList.contains("hidden-reset-step") ? "request" : !document.getElementById("resetCodeForm")?.classList.contains("hidden-reset-step") ? "code" : "password";
    setResetStep(activeResetStep);
  }
  if (typeof updateAccount === "function") updateAccount();
  updateFriendsMaintenanceLanguage(lang);
  const menu=document.getElementById("languageMenu");
  if(menu){
    const labels={ru:"Русский",en:"English",zh:"中文"};
    menu.querySelectorAll("[data-lang]").forEach(b=>b.textContent=labels[b.dataset.lang]);
  }
  document.querySelectorAll(".password-toggle").forEach(button=>{
    const input=button.parentElement?.querySelector("input[type='password'], input[type='text']");
    const visible=input?.type==="text";
    button.setAttribute("aria-label", visible ? tr("Скрыть пароль") : tr("Показать пароль"));
    button.setAttribute("title", visible ? tr("Скрыть пароль") : tr("Показать пароль"));
  });
  if(body){ body.dataset.i18nApplying="0"; document.documentElement.dataset.languageReady="1"; }
  if(animate && body){
    requestAnimationFrame(()=>setTimeout(()=>body.classList.remove("language-changing"),140));
  }
}
function setupLanguageSwitcher(){
  const toggle=document.getElementById("languageToggle");
  const menu=document.getElementById("languageMenu");
  const wrap=document.getElementById("languageSwitcher");
  if(!toggle||!menu||!wrap) return;

  const syncExpanded=()=>toggle.setAttribute("aria-expanded",menu.classList.contains("hidden")?"false":"true");
  const openMenu=()=>{ menu.classList.remove("hidden"); syncExpanded(); };
  const closeMenu=()=>{ menu.classList.add("hidden"); syncExpanded(); };

  // Use one click path only. Mobile browsers synthesize a click after touchend;
  // having both handlers made the menu open and immediately close again.
  toggle.addEventListener("click",e=>{
    e.preventDefault();
    e.stopPropagation();
    menu.classList.contains("hidden") ? openMenu() : closeMenu();
  });

  menu.querySelectorAll("[data-lang]").forEach(button=>{
    button.addEventListener("click",e=>{
      e.preventDefault();
      e.stopPropagation();
      const lang=button.dataset.lang;
      if(lang) applyLanguage(lang,true);
      closeMenu();
    });
  });

  document.addEventListener("click",e=>{
    if(!wrap.contains(e.target)) closeMenu();
  });
  syncExpanded();
  applyLanguage(currentLang(),false);
}
// Наблюдаем только за добавлением новых элементов.
// characterData здесь специально НЕ отслеживается: изменение текста внутри
// applyLanguage() само порождает MutationObserver-события и могло зациклить
// браузер, из-за чего сайт зависал и переставал принимать клики.
const i18nObserver = new MutationObserver(mutations=>{
  if(document.body?.dataset.i18nApplying==="1") return;
  mutations.forEach(m=>{
    m.addedNodes?.forEach(node=>{
      if(node.nodeType===Node.TEXT_NODE) {
        translateNode(node);
      } else if(node.nodeType===Node.ELEMENT_NODE) {
        translateAttributes(node);
        const w=document.createTreeWalker(node,NodeFilter.SHOW_TEXT);
        let n;
        while(n=w.nextNode()) translateNode(n);
        node.querySelectorAll?.("[placeholder],[aria-label],[title]").forEach(translateAttributes);
      }
    });
  });
});
if(document.body) i18nObserver.observe(document.body,{childList:true,subtree:true});


