function passwordStrength(value) {
  let score = 0;
  if (value.length >= 8) score++;
  if (value.length >= 12) score++;
  if (/[a-zа-я]/i.test(value) && /[A-ZА-Я]/.test(value)) score++;
  if (/\d/.test(value)) score++;
  if (/[^A-Za-zА-Яа-яЁё0-9]/.test(value)) score++;
  if (value.length < 8) return { level: "weak", percent: Math.min(value.length * 7, 25), text: value ? "Слабый" : "—", hint: "Добавь минимум 8 символов." };
  if (score <= 2) return { level: "weak", percent: 28, text: "Слабый", hint: "Добавь цифры, разные регистры и символ." };
  if (score === 3) return { level: "medium", percent: 52, text: "Средний", hint: "Ещё немного — добавь длину или символы." };
  if (score === 4) return { level: "good", percent: 76, text: "Хороший", hint: "Хорошо. Можно сделать пароль ещё длиннее." };
  return { level: "strong", percent: 100, text: "Надёжный", hint: "Отличный пароль." };
}

function renderStrength(input, box, text, bar, hint) {
  if (!input || !box) return;
  const result = passwordStrength(input.value);
  box.dataset.level = result.level;
  text.textContent = tr(result.text);
  bar.style.width = result.percent + "%";
  hint.textContent = tr(result.hint);
}

