const API_BASE = window.location.origin;

async function apiFetch(url, options = {}) {
  const token = localStorage.getItem("space_token") || "";
  const headers = { ...(options.headers || {}) };
  if (!headers["Content-Type"] && options.body) headers["Content-Type"] = "application/json";
  if (token) headers.Authorization = `Bearer ${token}`;
  const targetUrl = /^https?:\/\//i.test(url) ? url : `${API_BASE}${url}`;

  // Retry only network/time-out failures. HTTP 4xx/5xx responses are real
  // server responses and must be displayed immediately.
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 10000);
      try {
        const response = await fetch(targetUrl, { ...options, headers, credentials: "include", signal: controller.signal });
        sendActivity('api', `${options.method || 'GET'} ${new URL(targetUrl).pathname}`, `status=${response.status}`);
        const data = await response.json().catch(() => ({}));
        if (!response.ok) throw new Error(data.message || `Ошибка сервера (${response.status})`);
        return data;
      } finally { clearTimeout(timeout); }
    } catch (err) {
      const networkFailure = err?.name === 'AbortError' || err instanceof TypeError;
      if (!networkFailure) throw err;
      if (attempt === 1) throw new Error('Не удалось связаться с сервером. Проверьте подключение и попробуйте ещё раз.');
      await new Promise(r => setTimeout(r, 500));
    }
  }
  throw new Error('Не удалось связаться с сервером.');
}

function setSession(token, user) {
  if (!token || !user) return;
  localStorage.setItem("space_token", token);
  localStorage.setItem("space_session", JSON.stringify(user));
}
function getSession() {
  try {
    const token = localStorage.getItem("space_token");
    const user = JSON.parse(localStorage.getItem("space_session") || "null");
    if (!token || !user?.email || !user?.nick) return null;
    return user;
  } catch { return null; }
}
function clearSession() {
  localStorage.removeItem("space_token");
  localStorage.removeItem("space_session");
}

