// Sends only high-level activity. Never include input values, passwords, tokens or form contents.
function sendActivity(type, action, details = '') {
  try {
    const payload = JSON.stringify({
      type: String(type || 'event'),
      action: String(action || '').slice(0, 120),
      page: location.pathname + location.hash,
      details: String(details || '').slice(0, 180)
    });
    const headers = { 'Content-Type': 'application/json' };
    const token = localStorage.getItem('space_token') || '';
    if (token) headers.Authorization = `Bearer ${token}`;
    fetch(`${API_BASE}/api/log`, {
      method: 'POST',
      headers,
      body: payload,
      keepalive: true
    }).catch(() => {});
  } catch {}
}

