function formatActivity(lastSeen) {
  // In the profile/admin summary show only the current network state.
  // Exact last-seen time remains available in the separate activity history.
  if (!lastSeen) return tr("Офлайн");
  const timestamp = new Date(lastSeen).getTime();
  if (!Number.isFinite(timestamp)) return tr("Офлайн");
  return (Date.now() - timestamp) < 90 * 1000 ? tr("В сети") : tr("Офлайн");
}

function updateProfileActivity(lastSeen) {
  const el = document.getElementById("profileActivity");
  if (!el) return;
  const online = Number.isFinite(Number(lastSeen)) && Date.now() - Number(lastSeen) < 90 * 1000;
  el.textContent = formatActivity(lastSeen);
  el.classList.toggle("online", online);
  el.classList.toggle("offline", !online);

  const session = getSession() || {};
  const lastValue = document.getElementById("activityLastValue");
  if (lastValue) {
    if (lastSeen) {
      const d = new Date(lastSeen);
      lastValue.textContent = Number.isFinite(d.getTime()) ? d.toLocaleString(currentLang()==="zh"?"zh-CN":currentLang()==="en"?"en-US":"ru-RU", {dateStyle:"short", timeStyle:"short"}) : "—";
    } else lastValue.textContent = "—";
  }
  const ip = document.getElementById("profileActivityIp");
  const device = document.getElementById("profileActivityDevice");
  const screen = document.getElementById("profileActivityScreen");
  if (ip) ip.textContent = session.lastIp || "—";
  if (device) ip && (device.textContent = session.lastDevice || "—");
  if (screen) {
    const w=Number(session.screenWidth), h=Number(session.screenHeight), dpr=Number(session.screenDpr || session.devicePixelRatio);
    screen.textContent = w>0 && h>0 ? `${w} × ${h}${dpr>0 ? ` · DPR ${dpr}` : ""}` : "—";
  }
}

async function getClientActivityMeta() {
  const ua = String(navigator.userAgent || '');
  let deviceLabel = '';

  if (/Android/i.test(ua)) {
    deviceLabel = 'Android';
  } else if (/Windows/i.test(ua)) {
    // Chromium/Edge expose the actual Windows version through UA-CH.
    try {
      if (navigator.userAgentData?.getHighEntropyValues) {
        const hints = await navigator.userAgentData.getHighEntropyValues(['platformVersion']);
        const major = Number.parseInt(String(hints?.platformVersion || '').split('.')[0], 10);
        if (Number.isFinite(major)) deviceLabel = major >= 13 ? 'Windows 11' : major >= 10 ? 'Windows 10' : 'Windows';
      }
    } catch (_) {}
    if (!deviceLabel) deviceLabel = 'Windows';
  } else if (/Linux/i.test(ua)) {
    if (/Ubuntu/i.test(ua)) deviceLabel = 'Linux (Ubuntu)';
    else if (/Linux Mint|Mint/i.test(ua)) deviceLabel = 'Linux (Mint)';
    else deviceLabel = 'Linux';
  } else {
    deviceLabel = 'Неизвестное устройство';
  }

  return {
    screenWidth: Number(window.screen?.width || 0),
    screenHeight: Number(window.screen?.height || 0),
    devicePixelRatio: Number(window.devicePixelRatio || 1),
    deviceLabel
  };
}

let activityTimer = null;
async function sendActivityHeartbeat() {
  if (!hasCookieConsent() || !getSession() || document.visibilityState !== "visible") return;
  try {
    const data = await apiFetch("/api/auth/activity", { method:"POST", body:JSON.stringify(await getClientActivityMeta()) });
    const session = getSession();
    if (session && data?.lastSeen) {
      session.lastSeen = data.lastSeen;
      if (data.activity) {
        session.lastIp = data.activity.lastIp || null;
        session.lastDevice = data.activity.lastDevice || null;
        session.screenWidth = data.activity.screenWidth ?? null;
        session.screenHeight = data.activity.screenHeight ?? null;
        session.screenDpr = data.activity.screenDpr ?? null;
      }
      localStorage.setItem("space_session", JSON.stringify(session));
      updateProfileActivity(data.lastSeen);
    }
  } catch (_) {}
}
function startActivityHeartbeat() {
  if (activityTimer) clearInterval(activityTimer);
  sendActivityHeartbeat();
  activityTimer = setInterval(sendActivityHeartbeat, 30000);
}
function stopActivityHeartbeat() {
  if (activityTimer) { clearInterval(activityTimer); activityTimer = null; }
}
window.addEventListener("visibilitychange", () => {
  if (document.visibilityState === "visible") sendActivityHeartbeat();
});

function updateAccount() {
  const session = getSession();
  // Личный кабинет показываем только после успешного входа/регистрации.
  cabinetOpen.classList.toggle("hidden", !session);
  adminOpen.classList.toggle("hidden", !(session && (session.isAdmin || String(session.nick || "").trim().toLowerCase() === "winzuxx")));
  friendsOpen.classList.toggle("hidden", !session);
  accountName.classList.toggle("hidden", !session);
  loginOpen.classList.toggle("hidden", !!session);
  if (registerOpen) registerOpen.classList.toggle("hidden", !!session);

  // На телефоне после входа/регистрации убираем ТОЛЬКО верхние кнопки «Войти» и «Скачать».
  // Две кнопки скачивания в содержимом страницы (hero + нижний блок) всегда остаются.
  document.body.classList.toggle("mobile-authenticated", !!session);
  const topDownload = document.getElementById("downloadTop");
  if (topDownload) topDownload.classList.toggle("mobile-hide-auth", !!session);

  if (typeof updateBottomDownloadGate === "function") updateBottomDownloadGate();
  loginOpen.dataset.logged = session ? "1" : "0";
  if (session) {
    accountName.textContent = session.nick || session.email;
    if (hasCookieConsent()) startActivityHeartbeat();
    else stopActivityHeartbeat();
  } else {
    accountName.textContent = "";
    stopActivityHeartbeat();
  }
}

function openModal(newMode = "login") {
  mode = newMode;
  loginStep = "username";
  authError.textContent = "";
  form.reset();
  // Force a clean animation frame so every opening (Login/Register) animates smoothly.
  modal.classList.add("hidden");
  modal.classList.remove("is-closing");
  requestAnimationFrame(() => {
    modal.classList.remove("hidden");
    updateModal();
    requestAnimationFrame(() => modal.querySelector(".modal-window")?.focus?.());
  });
}

function closeModal() { closeAnimatedModal(modal); }

function updateModal() {
  // На шаге ввода пароля вкладки «Вход / Регистрация» плавно скрываются.
  // На шаге ввода имени они остаются доступными.
  modal.classList.toggle("login-password-step", mode === "login" && loginStep === "password");

  document.querySelectorAll(".tab").forEach(tab => {
    tab.classList.toggle("active", tab.dataset.mode === mode);
  });

  if (mode === "login") {
    emailField.classList.add("hidden-field");
    emailInput.required = false;
    emailInput.disabled = true;
    emailInput.autocomplete = "off";

    nickField.classList.remove("hidden-field");
    nickField.classList.remove("show");
    nickInput.required = true;
    nickInput.disabled = false;
    nickInput.placeholder = tr("Имя пользователя");
    nickInput.autocomplete = "username";

    if (loginStep === "username") {
      authPasswordField.classList.add("hidden-field");
      authPasswordField.classList.remove("show");
      passwordInput.required = false;
      passwordInput.disabled = true;
      passwordInput.autocomplete = "off";
      authPasswordStrength.classList.add("hidden");
      document.getElementById("modalTitle").textContent = tr("С возвращением");
      document.getElementById("modalDescription").textContent = tr("Введи имя пользователя, чтобы продолжить.");
      authBack.classList.add("hidden");
      document.getElementById("authSubmit").textContent = tr("Продолжить");
    } else {
      nickField.classList.add("hidden-field");
      authPasswordField.classList.remove("hidden-field");
      authPasswordField.classList.add("show");
      passwordInput.required = true;
      passwordInput.disabled = false;
      passwordInput.autocomplete = "current-password";
      authPasswordStrength.classList.add("hidden");
      document.getElementById("modalTitle").textContent = tr("Пароль от аккаунта");
      document.getElementById("modalDescription").textContent = `${tr("Аккаунт:")} ${nickInput.value.trim()}`;
      authBack.classList.remove("hidden");
      document.getElementById("authSubmit").textContent = tr("Войти");
    }
  } else {
    nickField.classList.remove("hidden-field");
    nickField.classList.add("show");
    emailField.classList.remove("hidden-field");
    emailInput.required = true;
    emailInput.disabled = false;
    emailInput.autocomplete = "email";
    nickInput.required = true;
    nickInput.disabled = false;
    nickInput.placeholder = tr("Имя пользователя");
    nickInput.autocomplete = "username";
    authPasswordField.classList.remove("hidden-field");
    authPasswordField.classList.add("show");
    passwordInput.required = true;
    passwordInput.disabled = false;
    authPasswordStrength.classList.remove("hidden");
    renderStrength(passwordInput, authPasswordStrength, authStrengthText, authStrengthBar, authStrengthHint);
    passwordInput.autocomplete = "new-password";
    document.getElementById("modalTitle").textContent = tr("Создать аккаунт");
    document.getElementById("modalDescription").textContent = tr("Регистрация займёт несколько секунд.");
    authBack.classList.add("hidden");
    document.getElementById("authSubmit").textContent = tr("Зарегистрироваться");
  }
}

