// Universal smooth closing for every modal. The backdrop and the window animate together.
const MODAL_CLOSE_MS = 360;
const modalCloseTimers = new WeakMap();
function closeAnimatedModal(modal, afterClose) {
  if (!modal || modal.classList.contains("hidden")) return;
  const oldTimer = modalCloseTimers.get(modal);
  if (oldTimer) clearTimeout(oldTimer);
  modal.classList.add("is-closing");
  const timer = setTimeout(() => {
    modal.classList.add("hidden");
    modal.classList.remove("is-closing", "cabinet-closing");
    modalCloseTimers.delete(modal);
    if (typeof afterClose === "function") afterClose();
  }, MODAL_CLOSE_MS);
  modalCloseTimers.set(modal, timer);
}
