form.addEventListener("submit", async e => {
  e.preventDefault();
  authError.textContent = "";
  const nick = nickInput.value.trim();
  const password = passwordInput.value;

  if (mode === "login" && loginStep === "username") {
    if (!nick) { authError.textContent = tr("Введите имя пользователя."); return; }
    // Проверяем ник на сервере, а не в localStorage.
    try {
      await apiFetch("/api/auth/check-username", { method:"POST", body:JSON.stringify({ nick }) });
      // Username exists — move to the password step.
      loginStep = "password";
      updateModal();
      refreshKnownUiLanguage();
      requestAnimationFrame(() => passwordInput.focus());
      return;
    } catch (e) {
      const legacy = findUserByNick(nick);
      if (legacy?.user?.password) {
        await migrateLocalAccount(legacy.user);
        loginStep = "password"; updateModal(); refreshKnownUiLanguage(); passwordInput.focus(); return;
      }
      authError.textContent = tr(e.message || "Аккаунт с таким именем пользователя не найден.");
      return;
    }
  }

  if (password.length < 8) { authError.textContent = tr("Пароль должен содержать минимум 8 символов."); passwordInput.focus(); return; }

  if (mode === "register") {
    const email = emailInput.value.trim().toLowerCase();
    if (!/^[A-Za-zА-Яа-яЁё0-9_ .-]{3,24}$/.test(nick)) { authError.textContent = tr("Имя пользователя: 3–24 символа, без спецсимволов."); return; }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { authError.textContent = tr("Введите корректную почту."); return; }
    try {
      const data = await apiFetch("/api/auth/register", { method:"POST", body:JSON.stringify({ nick, email, password, ...(await getClientActivityMeta()) }) });
      setSession(data.token, data.user); closeModal(); updateAccount(); toastMsg("Успешная регистрация");
    } catch (e) { authError.textContent = tr(e.message); }
    return;
  }

  try {
    let data;
    try {
      data = await apiFetch("/api/auth/login", { method:"POST", body:JSON.stringify({ nick, password, ...(await getClientActivityMeta()) }) });
    } catch (e) {
      const legacy = findUserByNick(nick);
      if (legacy?.user?.password === password) {
        await migrateLocalAccount(legacy.user);
        data = await apiFetch("/api/auth/login", { method:"POST", body:JSON.stringify({ nick, password, ...(await getClientActivityMeta()) }) });
      } else throw e;
    }
    setSession(data.token, data.user); closeModal(); updateAccount(); toastMsg("Успешный вход");
  } catch (e) { authError.textContent = tr(e.message || "Неверный пароль."); passwordInput.focus(); }
});

async function openCabinet() {
  const session = getSession();
  if (!session) return openModal("login");
  try {
    const data = await apiFetch("/api/auth/me");
    setSession(localStorage.getItem("space_token"), data.user);
    const user = data.user;
    document.getElementById("profileNick").textContent = user.nick || "—";
    document.getElementById("profileEmail").textContent = user.email || "—";
    updateProfileActivity(user.lastSeen);
    cabinetModal.classList.remove("hidden", "cabinet-closing");
    updateAccount();
  } catch (e) {
    clearSession(); updateAccount(); toastMsg(tr(e.message || "Не удалось загрузить профиль."));
  }
}


