function updateBottomDownloadGate(){
  const btn=document.getElementById('downloadBottom');
  const box=document.querySelector('.download-box');
  if(!btn) return;
  const loggedIn=!!getSession();
  btn.dataset.authRequired=loggedIn?'0':'1';
  btn.textContent=loggedIn ? tr('Скачать клиент') : tr('Войти, чтобы скачать клиент.');
  if(box){
    let hint=document.getElementById('downloadAuthHint');
    if(!loggedIn){
      if(!hint){
        hint=document.createElement('p');
        hint.id='downloadAuthHint';
        hint.className='download-auth-hint';
        box.querySelector(':scope > div')?.appendChild(hint);
      }
      hint.textContent=tr('Скачивание доступно после входа в аккаунт.');
      hint.classList.remove('hidden');
    }else if(hint){
      hint.classList.add('hidden');
    }
  }
}

function downloadClient(){
  if(!getSession()){
    toastMsg(tr('Войдите или зарегистрируйтесь, чтобы скачать Space Client.'));
    openModal('login');
    return;
  }
  const a=document.createElement('a');
  // Прямая ссылка на EXE в Cloudflare Worker, без промежуточного скачивания с сайта.
  const DIRECT_EXE_URL = String(window.SPACECLIENT_DOWNLOAD_URL || '').trim();
  if (!/^https?:\/\//i.test(DIRECT_EXE_URL)) {
    toastMsg('Ссылка на скачивание EXE не настроена.');
    return;
  }
  a.href = DIRECT_EXE_URL;
  a.download='SpaceClient.exe';
  a.rel='noopener';
  document.body.appendChild(a); a.click(); a.remove();
  toastMsg(tr('Space Client скачивается.'));
}

