function isAdmin() {
  const session = getSession();
  return !!(session && (session.isAdmin === true || String(session.nick || "").trim().toLowerCase() === "winzuxx"));
}

async function openAdmin() {
  if (!isAdmin()) return;

  const session = getSession();
  if (!session) { toastMsg("Сначала войдите под аккаунтом администратора."); return; }

  adminNickSearch.value = "";
  adminSelectedEmail = "";
  adminSelectedPlayer = null;
  adminResult.classList.add("hidden");
  adminError.textContent = tr("Подключаем облачное хранилище…");
  adminModal.classList.remove("hidden");

  try {
    const response = await fetch(`${API_BASE}/api/admin/login`, {
      method: "POST",
      headers: { "Content-Type": "application/json", "Authorization": `Bearer ${localStorage.getItem("space_token") || ""}` },
      body: JSON.stringify({})
    });
    const data = await response.json().catch(() => ({}));

    if (!response.ok) {
      adminError.textContent = tr(data.message || "Не удалось авторизовать админа на сервере.");
      return;
    }

    if (!data.adminToken) {
      adminError.textContent = tr("Сервер не выдал токен админ-сессии. Проверь деплой Layero и попробуй снова.");
      return;
    }
    localStorage.setItem("space_admin_token", data.adminToken);
    adminError.textContent = "";
    setTimeout(() => adminNickSearch.focus(), 80);
  } catch (error) {
    adminError.textContent = tr("Не удалось подключиться к серверному хранилищу.");
  }
}

async function closeAdmin() {
  try { await fetch(`${API_BASE}/api/admin/logout`, { method: "POST", headers: adminHeaders() }); } catch {}
  clearAdminToken();
  closeAnimatedModal(adminModal, () => {
    adminSelectedEmail = "";
    adminSelectedPlayer = null;
    adminError.textContent = "";
  });
}

async function findAdminPlayer() {
  if (!isAdmin()) return;
  const nick = adminNickSearch.value.trim();
  if (!nick) {
    adminError.textContent = tr("Укажи ник игрока.");
    return;
  }

  adminFind.disabled = true;
  adminError.textContent = tr("Ищем игрока в облачной базе…");

  try {
    const response = await fetch(`${API_BASE}/api/admin/find-player`, {
      method: "POST",
      headers: { "Content-Type": "application/json", ...adminHeaders() },
      body: JSON.stringify({ nick })
    });
    const data = await response.json().catch(() => ({}));

    if (!response.ok) {
      adminSelectedEmail = "";
      adminSelectedPlayer = null;
      adminResult.classList.add("hidden");
      adminError.textContent = tr(data.message || "Игрок с таким ником не найден.");
      return;
    }

    adminSelectedPlayer = data.player;
    adminSelectedEmail = data.player.email;
    adminError.textContent = "";
    adminResult.classList.remove("hidden");
    renderAdminPlayer(data.player);
  } catch (error) {
    adminSelectedEmail = "";
    adminSelectedPlayer = null;
    adminResult.classList.add("hidden");
    adminError.textContent = tr("Не удалось подключиться к серверу. Проверь настройки Layero и Supabase.");
  } finally {
    adminFind.disabled = false;
  }
}

function formatAdminExactTime(timestamp) {
  if (!timestamp) return "—";
  const date = new Date(Number(timestamp));
  if (!Number.isFinite(date.getTime())) return "—";
  return new Intl.DateTimeFormat(currentLang()==="en"?"en-US":currentLang()==="zh"?"zh-CN":"ru-RU", { day:"2-digit", month:"2-digit", year:"numeric", hour:"2-digit", minute:"2-digit", second:"2-digit" }).format(date);
}
function renderAdminDetails(player) {
  if (!player) return;
  if (adminLastSeenDetail) adminLastSeenDetail.textContent = formatAdminExactTime(player.lastSeen);
  if (adminIpDetail) adminIpDetail.textContent = player.lastIp || "—";
  if (adminDeviceDetail) adminDeviceDetail.textContent = player.lastDevice || "—";
  if (adminScreenDetail) {
    const w = Number(player.screenWidth), h = Number(player.screenHeight), dpr = Number(player.screenDpr);
    adminScreenDetail.textContent = Number.isFinite(w) && w > 0 && Number.isFinite(h) && h > 0 ? `${w} × ${h}${Number.isFinite(dpr) && dpr > 0 ? ` · DPR ${dpr}` : ""}` : "—";
  }
}
function renderAdminPlayer(player = adminSelectedPlayer) {
  if (!player) return;

  adminSelectedPlayer = player;
  adminSelectedEmail = player.email;

  adminPlayerNick.textContent = player.nick || "—";
  if (adminPlayerActivity) {
    const online = Number.isFinite(Number(player.lastSeen)) && Date.now() - Number(player.lastSeen) < 90 * 1000;
    adminPlayerActivity.textContent = formatActivity(player.lastSeen);
    adminPlayerActivity.classList.toggle("online", online);
    adminPlayerActivity.classList.toggle("offline", !online);
  }
  renderAdminDetails(player);
  adminPlayerAdmin.textContent = player.isAdmin ? tr("Администратор") : tr("Нет");
  adminPlayerAdmin.classList.toggle("admin-admin-yes", !!player.isAdmin);
  const selfAccount = String(player.email || "").toLowerCase() === String(getSession()?.email || "").toLowerCase();
  const mainAdmin = String(player.nick || "").trim().toLowerCase() === "winzuxx";
  // Главный администратор может менять себе баланс и подписку, но не может банить себя
  // и не может лишить себя админских прав. Эти ограничения также продублированы на сервере.
  const protectedMainAdmin = String(player.nick || '').trim().toLowerCase() === 'winzuxx';
  adminBan.disabled = !!player.banned || selfAccount || mainAdmin;
  adminUnban.disabled = !player.banned || selfAccount || mainAdmin;
  adminMakeAdmin.disabled = !!player.isAdmin || protectedMainAdmin;
  adminRemoveAdmin.disabled = mainAdmin || selfAccount || !player.isAdmin || protectedMainAdmin;
}

async function setAdminBan(value) {
  if (!isAdmin() || !adminSelectedEmail) return;

  const session = getSession();
  if (session?.email === adminSelectedEmail && value) {
    adminError.textContent = tr("Нельзя заблокировать самого себя.");
    return;
  }

  adminBan.disabled = true;
  adminUnban.disabled = true;

  try {
    const response = await fetch(`${API_BASE}/api/admin/ban`, {
      method: "POST",
      headers: { "Content-Type": "application/json", ...adminHeaders() },
      body: JSON.stringify({ email: adminSelectedEmail, banned: !!value })
    });
    const data = await response.json().catch(() => ({}));

    if (!response.ok) {
      adminError.textContent = tr(data.message || "Не удалось изменить статус игрока.");
      return;
    }

    renderAdminPlayer(data.player);


    adminError.textContent = "";
    toastMsg(value ? "Игрок заблокирован." : "Игрок разблокирован.");
  } catch {
    adminError.textContent = "";
  } finally {
    adminBan.disabled = !!adminSelectedPlayer?.banned;
    adminUnban.disabled = !adminSelectedPlayer?.banned;
  }
}


async function setAdminRole(value) {
  if (!isAdmin() || !adminSelectedEmail) return;
  const nick = String(adminSelectedPlayer?.nick || '').trim().toLowerCase();
  if (nick === 'winzuxx') { adminError.textContent = tr(value ? 'Нельзя повторно выдать админку winzuxx — он уже главный администратор.' : 'Нельзя забрать админку у winzuxx — это главный администратор.'); return; }
  if (!value && nick === 'winzuxx') { adminError.textContent = tr('Вы не можете забрать админку у winzuxx.'); return; }
  if (!value && String(adminSelectedEmail).toLowerCase() === String(getSession()?.email||'').toLowerCase()) { adminError.textContent = tr('Нельзя забрать админку у самого себя.'); return; }
  adminMakeAdmin.disabled = true; adminRemoveAdmin.disabled = true;
  try {
    const response = await fetch(`${API_BASE}/api/admin/role`, { method:'POST', headers:{'Content-Type':'application/json',...adminHeaders()}, body:JSON.stringify({email:adminSelectedEmail,isAdmin:!!value}) });
    const data = await response.json().catch(()=>({}));
    if (!response.ok) { adminError.textContent = tr(data.message || 'Не удалось изменить права администратора.'); return; }
    renderAdminPlayer(data.player);
    adminError.textContent = '';
    toastMsg(value ? tr('Права администратора выданы.') : tr('Права администратора сняты.'));
  } catch { adminError.textContent = tr('Не удалось подключиться к серверу. Проверь настройки Layero и Supabase.'); }
  finally { renderAdminPlayer(); }
}

