const resetModal = document.getElementById("resetModal");
const resetClose = document.getElementById("resetClose");
const resetX = document.getElementById("resetX");
const resetBack = document.getElementById("resetBack");
const resetStepRequest = document.getElementById("resetStepRequest");
const resetCodeForm = document.getElementById("resetCodeForm");
const resetPasswordForm = document.getElementById("resetPasswordForm");
const resetNick = document.getElementById("resetNick");
const resetEmailMasked = document.getElementById("resetEmailMasked");
const sendResetCode = document.getElementById("sendResetCode");
const resetCode = document.getElementById("resetCode");
const resetCodeError = document.getElementById("resetCodeError");
const resendResetCode = document.getElementById("resendResetCode");
const resendTimer = document.getElementById("resendTimer");
const resetNewPassword = document.getElementById("resetNewPassword");
const resetConfirmPassword = document.getElementById("resetConfirmPassword");
const resetPasswordError = document.getElementById("resetPasswordError");
const resetPasswordStrength = document.getElementById("resetPasswordStrength");
const resetStrengthText = document.getElementById("resetStrengthText");
const resetStrengthBar = document.getElementById("resetStrengthBar");
const resetStrengthHint = document.getElementById("resetStrengthHint");
const resetTitle = document.getElementById("resetTitle");
const resetDescription = document.getElementById("resetDescription");

let pendingResetEmail = "";
let resetToken = "";
let resendCount = 0;
let resendInterval = null;
const resendDelays = [60, 120, 180, 360];

function maskEmail(email) {
  const [name, domain] = String(email || "").split("@");
  if (!name || !domain) return email || "";
  const visible = name.length <= 2 ? name[0] : name.slice(0, 2);
  return `${visible}${"•".repeat(Math.max(1, Math.min(5, name.length - visible.length)))}@${domain}`;
}

function setResetStep(step) {
  resetStepRequest.classList.toggle("hidden-reset-step", step !== "request");
  resetCodeForm.classList.toggle("hidden-reset-step", step !== "code");
  resetPasswordForm.classList.toggle("hidden-reset-step", step !== "password");
  if (step === "request") {
    resetTitle.textContent = tr("Сброс пароля");
    resetDescription.textContent = tr("Код подтверждения будет отправлен на почту аккаунта.");
  } else if (step === "code") {
    resetTitle.textContent = tr("Введи код из письма");
    resetDescription.textContent = `${tr("Мы отправили 6-значный код на")} ${maskEmail(pendingResetEmail)}.`;
  } else {
    resetTitle.textContent = tr("Новый пароль");
    resetDescription.textContent = tr("Придумай новый пароль для своего аккаунта.");
  }
}

function stopResendTimer() {
  if (resendInterval) clearInterval(resendInterval);
  resendInterval = null;
}

function startResendTimer(seconds) {
  stopResendTimer();
  let left = Math.max(0, Number(seconds) || 0);
  resendResetCode.disabled = left > 0;
  resendTimer.textContent = left;
  resendInterval = setInterval(() => {
    left -= 1;
    resendTimer.textContent = Math.max(0, left);
    if (left <= 0) {
      stopResendTimer();
      resendResetCode.disabled = false;
      resendResetCode.innerHTML = tr("Отправить код снова");
    }
  }, 1000);
}

async function openResetPassword() {
  const nick = nickInput.value.trim();
  if (!nick) { authError.textContent = tr("Сначала укажи имя пользователя."); nickInput.focus(); return; }
  try {
    const data = await apiFetch("/api/auth/check-username", { method:"POST", body:JSON.stringify({ nick }) });
    pendingResetEmail = data.email;
    resetToken = ""; resendCount = 0;
    resetNick.textContent = data.nick || nick;
    resetEmailMasked.textContent = maskEmail(data.email);
    resetCode.value = ""; resetNewPassword.value = ""; resetConfirmPassword.value = "";
    resetCodeError.textContent = ""; resetPasswordError.textContent = "";
    setResetStep("request"); resetModal.classList.remove("hidden");
  } catch (e) { authError.textContent = tr(e.message || "Аккаунт не найден."); }
}

function closeResetPassword() {
  stopResendTimer();
  closeAnimatedModal(resetModal, () => {
    pendingResetEmail = "";
    resetToken = "";
  });
}

async function sendResetRequest(isResend = false) {
  if (!pendingResetEmail) return;
  sendResetCode.disabled = true;
  resendResetCode.disabled = true;
  const button = isResend ? resendResetCode : sendResetCode;
  const original = isResend ? resendResetCode.innerHTML : sendResetCode.textContent;
  button.textContent = tr("Отправляем…");

  try {
    const response = await fetch(`${API_BASE}/api/auth/forgot-password`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email: pendingResetEmail })
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.message || "Не удалось отправить код.");

    if (isResend) resendCount = Math.min(resendCount + 1, resendDelays.length - 1);
    setResetStep("code");
    startResendTimer(data.retryAfter || resendDelays[Math.min(resendCount, resendDelays.length - 1)]);
    resetCode.focus();
    toastMsg("Код отправлен на почту.");
  } catch (error) {
    toastMsg(tr(error.message || "Не удалось отправить код."));
    if (isResend) resendResetCode.disabled = false;
    else sendResetCode.disabled = false;
  } finally {
    button.textContent = tr(original);
  }
}

forgotPassword.addEventListener("click", openResetPassword);
resetClose.addEventListener("click", closeResetPassword);
resetX.addEventListener("click", closeResetPassword);
resetBack.addEventListener("click", () => {
  closeResetPassword();
  openModal("login");
  loginStep = "password";
  updateModal();
  if (passwordInput) passwordInput.focus();
});
sendResetCode.addEventListener("click", () => sendResetRequest(false));
resendResetCode.addEventListener("click", () => sendResetRequest(true));

resetCodeForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  resetCodeError.textContent = "";
  const code = resetCode.value.trim();
  if (!/^\d{6}$/.test(code)) {
    resetCodeError.textContent = tr("Введи 6-значный код из письма.");
    resetCode.focus();
    return;
  }

  const button = document.getElementById("verifyResetCode");
  button.disabled = true;
  try {
    const response = await fetch(`${API_BASE}/api/auth/verify-reset-code`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email: pendingResetEmail, code })
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.message || tr("Неверный или просроченный код."));
    resetToken = data.token || "";
    setResetStep("password");
    resetNewPassword.focus();
  } catch (error) {
    resetCodeError.textContent = tr(error.message || "Неверный или просроченный код.");
    resetCode.focus();
  } finally {
    button.disabled = false;
  }
});

resetNewPassword.addEventListener("input", () => {
  renderStrength(resetNewPassword, resetPasswordStrength, resetStrengthText, resetStrengthBar, resetStrengthHint);
});

resetPasswordForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  resetPasswordError.textContent = "";
  if (!resetToken) {
    resetPasswordError.textContent = tr("Сначала подтверди код из письма.");
    setResetStep("code");
    return;
  }
  if (resetNewPassword.value.length < 8) {
    resetPasswordError.textContent = tr("Пароль должен содержать минимум 8 символов.");
    resetNewPassword.focus();
    return;
  }
  if (resetNewPassword.value !== resetConfirmPassword.value) {
    resetPasswordError.textContent = tr("Новые пароли не совпадают.");
    resetConfirmPassword.focus();
    return;
  }

  const button = resetPasswordForm.querySelector("button[type='submit']");
  button.disabled = true;
  try {
    const response = await fetch(`${API_BASE}/api/auth/reset-password`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email: pendingResetEmail, token: resetToken, password: resetNewPassword.value })
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.message || tr("Не удалось изменить пароль."));

    closeResetPassword();
    openModal("login");
    const remoteUser = await fetch(`${API_BASE}/api/auth/login`, { method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({nick:document.getElementById("resetNick").textContent, password:resetNewPassword.value}) }).then(r=>r.ok?r.json():null).catch(()=>null);
    if (remoteUser?.token) { setSession(remoteUser.token, remoteUser.user); closeModal(); updateAccount(); }
    authError.textContent = tr("Пароль изменён. Войди с новым паролем.");
    toastMsg(tr("Пароль успешно изменён."));
  } catch (error) {
    resetPasswordError.textContent = tr(error.message || "Не удалось изменить пароль.");
  } finally {
    button.disabled = false;
  }
});


/* ===== Background music: playlist (1.mp3, 2.mp3, ...), collapsible panel + persistent volume ===== */
(function setupAmbientAudio(){
  const audio=document.getElementById('ambientAudio');
  const toggle=document.getElementById('ambientToggle');
  const panel=document.querySelector('.ambient-controls');
  const status=document.getElementById('ambientStatus');
  const volume=document.getElementById('ambientVolume');
  const value=document.getElementById('ambientVolumeValue');
  const power=document.getElementById('ambientPower');
  if(!audio||!toggle||!panel||!volume)return;

  const clamp=(n,min,max)=>Math.min(max,Math.max(min,n));
  let enabled=localStorage.getItem('space_music_enabled')!=='0';
  let savedVolume=clamp(Math.round(Number(localStorage.getItem('space_music_volume')||8)),5,1000);
  let statusTimer=null;
  let ctx=null, source=null, gain=null;
  let playlist=[];
  let trackIndex=0;
  let playlistLoaded=false;
  let loadingPlaylist=null;

  function statusMsg(msg,on=enabled){
    if(!status)return;
    status.textContent=msg;
    status.classList.remove('on','off','show');
    status.classList.add(on?'on':'off');
    void status.offsetWidth;
    status.classList.add('show');
    clearTimeout(statusTimer);
    statusTimer=setTimeout(()=>status.classList.remove('show'),2600);
  }

  function ensureGraph(){
    if(ctx) return true;
    try{
      const AC=window.AudioContext||window.webkitAudioContext;
      if(!AC)return false;
      ctx=new AC();
      source=ctx.createMediaElementSource(audio);
      gain=ctx.createGain();
      source.connect(gain);
      gain.connect(ctx.destination);
      return true;
    }catch(err){
      console.warn('Ambient audio graph unavailable:',err);
      return false;
    }
  }

  function applyVolume(){
    savedVolume=clamp(savedVolume,5,1000);
    volume.value=String(savedVolume);
    if(value)value.textContent=savedVolume+'%';
    volume.style.setProperty('--volume-pos',((savedVolume-5)/995*100)+'%');
    if(gain){ gain.gain.value=savedVolume/100; audio.volume=1; }
    else audio.volume=Math.min(1,savedVolume/100);
  }

  function syncPower(){
    toggle.classList.toggle('is-muted',!enabled);
    toggle.textContent=enabled?'♫':'♪';
    toggle.setAttribute('aria-label',panel.classList.contains('is-hidden')?tr('Открыть управление музыкой'):(enabled?tr('Выключить музыку'):tr('Включить музыку')));
    if(power){
      power.textContent=enabled?tr('Музыка: включена'):tr('Музыка: выключена');
      power.classList.toggle('off',!enabled);
    }
    applyVolume();
  }

  async function loadPlaylist(){
    if(playlistLoaded) return playlist;
    if(loadingPlaylist) return loadingPlaylist;
    loadingPlaylist=fetch('/api/music',{cache:'no-store'})
      .then(r=>r.ok?r.json():Promise.reject(new Error('playlist '+r.status)))
      .then(data=>{
        playlist=Array.isArray(data.tracks)?data.tracks:[];
        playlistLoaded=true;
        return playlist;
      })
      .catch(err=>{
        console.warn('Music playlist failed:',err);
        // Local fallback for a static preview / old deployment.
        playlist=['/music/1.mp3'];
        playlistLoaded=true;
        return playlist;
      })
      .finally(()=>{loadingPlaylist=null;});
    return loadingPlaylist;
  }

  function setTrack(index, autoplay=false){
    if(!playlist.length) return false;
    trackIndex=((index%playlist.length)+playlist.length)%playlist.length;
    const src=playlist[trackIndex];
    if(audio.getAttribute('src')!==src){
      audio.src=src;
      audio.load();
    }
    if(autoplay) return audio.play().then(()=>true).catch(()=>false);
    return true;
  }

  async function startMusic(show=true){
    try{
      if(!enabled)return false;
      const list=await loadPlaylist();
      if(!list.length){
        if(show)statusMsg(tr('В папке music нет песен'),false);
        return false;
      }
      if(!audio.src || !playlist.length || !audio.getAttribute('src')) setTrack(trackIndex,false);
      ensureGraph();
      if(ctx && ctx.state==='suspended') await ctx.resume();
      applyVolume();
      audio.muted=false;
      await audio.play();
      if(show)statusMsg(tr('Музыка включена')+' · '+savedVolume+'%',true);
      return true;
    }catch(err){
      console.warn('Music playback failed:',err);
      if(show)statusMsg(tr('Нажми «Музыка: включена» ещё раз'),false);
      return false;
    }
  }

  function stopMusic(show=true){
    audio.pause();
    audio.muted=true;
    if(show)statusMsg(tr('Музыка отключена'),false);
  }

  function openPanel(){ panel.classList.remove('is-hidden'); toggle.classList.add('panel-open'); syncPower(); }
  function closePanel(){ panel.classList.add('is-hidden'); toggle.classList.remove('panel-open'); syncPower(); }
  function togglePanel(){ if(panel.classList.contains('is-hidden')) openPanel(); else closePanel(); }

  volume.addEventListener('input',()=>{
    savedVolume=clamp(Math.round(Number(volume.value)||5),5,1000);
    localStorage.setItem('space_music_volume',String(savedVolume));
    if(savedVolume>100) ensureGraph();
    applyVolume();
    if(status) statusMsg(tr('♫ Громкость: ') + savedVolume+'%',true);
  });

  toggle.addEventListener('click',async e=>{
    e.preventDefault(); e.stopPropagation();
    const wasHidden=panel.classList.contains('is-hidden');
    togglePanel();
    if(wasHidden && enabled && audio.paused) await startMusic(true);
  });

  if(power) power.addEventListener('click',async e=>{
    e.preventDefault(); e.stopPropagation();
    enabled=!enabled;
    localStorage.setItem('space_music_enabled',enabled?'1':'0');
    if(enabled){ syncPower(); await startMusic(true); }
    else { syncPower(); stopMusic(true); }
  });

  audio.addEventListener('ended',async()=>{
    if(!enabled) return;
    if(!playlist.length) await loadPlaylist();
    if(playlist.length){
      trackIndex=(trackIndex+1)%playlist.length;
      setTrack(trackIndex,false);
      try{
        if(ctx && ctx.state==='suspended') await ctx.resume();
        audio.muted=false;
        await audio.play();
      }catch(err){ console.warn('Next track playback failed:',err); }
    }
  });

  audio.addEventListener('error',()=>{
    console.warn('Ambient file failed to load:',audio.error, audio.currentSrc);
    statusMsg(tr('Не удалось загрузить песню из папки music'),false);
  });
  audio.addEventListener('canplay',()=>applyVolume());

  applyVolume();
  syncPower();
  closePanel();
  loadPlaylist().then(list=>{ if(list.length) setTrack(trackIndex,false); });

  const unlock=async()=>{
    if(enabled && audio.paused) await startMusic(false);
    document.removeEventListener('pointerdown',unlock,true);
    document.removeEventListener('keydown',unlock,true);
    document.removeEventListener('touchstart',unlock,true);
  };
  document.addEventListener('pointerdown',unlock,true);
  document.addEventListener('keydown',unlock,true);
  document.addEventListener('touchstart',unlock,true);
})();


