/* Patch the existing ambient controls without replacing the rest of the application. */
(function patchAmbientV12(){
  const value=document.getElementById('ambientVolumeValue');
  const volume=document.getElementById('ambientVolume');
  if(!value||!volume) return;
  value.title=tr('Громкость');
  value.style.cursor='pointer';
  value.setAttribute('role','button');
  value.setAttribute('tabindex','0');
  const edit=()=>{
    const current=Math.round(Number(volume.value)||8);
    const raw=window.prompt(tr('Введите громкость от 5 до 1000%:'), String(current));
    if(raw===null) return;
    const cleaned=String(raw).replace('%','').trim().replace(',','.');
    const n=Number(cleaned);
    if(!Number.isFinite(n) || n<5 || n>1000){
      if(typeof statusMsg==='function') statusMsg(tr('Громкость должна быть числом от 5 до 1000%.'),false);
      else alert(tr('Громкость должна быть числом от 5 до 1000%.'));
      return;
    }
    volume.value=String(Math.round(n));
    volume.dispatchEvent(new Event('input',{bubbles:true}));
  };
  value.addEventListener('click',edit);
  value.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();edit();}});

  // Do not observe this element with MutationObserver. The old observer wrote
  // textContent from inside its own callback, which created an endless mutation
  // loop and eventually froze scrolling/clicks on the page. The normal volume
  // input handler already keeps this value up to date.
})();

/* Make browser-gesture playback reliable: never wait for /api/music before the first play(). */
(function patchAmbientPlaybackV12(){
  const audio=document.getElementById('ambientAudio');
  if(!audio) return;
  const fallback='/music/1.mp3';
  const ensureImmediateSource=()=>{
    if(!audio.getAttribute('src')){
      audio.src=fallback;
      audio.load();
    }
  };
  ['pointerdown','touchstart','keydown'].forEach(type=>document.addEventListener(type,()=>{
    try{
      const enabled=localStorage.getItem('space_music_enabled')!=='0';
      if(enabled && audio.paused){
        ensureImmediateSource();
        const p=audio.play();
        if(p && p.catch) p.catch(()=>{});
      }
    }catch(e){}
  },{capture:true,passive:true,once:false}));
})();
